{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Sacubitril, the highest-transfer analogue, has an absolute oral bioavailability of 60% in healthy subjects despite containing a free carboxylic acid and amide, supporting high F for the query's acid/amide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Letermovir, which shares high molecular weight, a carboxylic acid, methoxy/aromatic groups, and complex polar features, has an absolute bioavailability of 93.8% in healthy participants, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Tianeptine, a carboxylic acid-containing amide/sulfonamide drug, has an absolute bioavailability of about 99% in healthy young volunteers, supporting high F despite an ionizable acid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Zafirlukast, a high-molecular-weight, highly functionalized oral drug, has about 35% bioavailability in humans, showing that high polarity and complexity do not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Idasanutlin, sharing high molecular weight, carboxylic acid, amide, and aromatic features with the query, has an absolute bioavailability of 40.1% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A fed-state microprecipitated bulk powder formulation of idasanutlin gave F = 18.7%, a single condition/formulation-specific value below 20%; this is contradictory but outweighed by the 40.1% patient value and the overall high-bioavailability analogue pattern.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All high-transfer experimental analogues with carboxylic acid, amide/urea, and high-molecular-weight features show human absolute oral bioavailability ≥34% (mostly 40–99%), strongly supporting F ≥ 20% for the query. The single fed-state low value for idasanutlin is formulation-specific and outweighed by consistent supportive evidence.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the exact query molecule.",
    "The query's very high TPSA (155.5 Å²) and full ionization at physiological pH are at the extreme of the analogue set, so the quantitative F value is uncertain even though the threshold prediction is supported.",
    "No direct permeability, efflux, or metabolism data are available for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

